WITH orders_by_store AS (SELECT store_id, COUNT(DISTINCT discount) AS unique_customers, ROUND(STDDEV(amount), 2) AS stddev_amount FROM orders WHERE amount <= 1450 GROUP BY store_id) SELECT s.id, s.opened_date, s.store_name, obs.unique_customers, obs.stddev_amount FROM stores s INNER JOIN orders_by_store obs ON s.id = obs.store_id WHERE obs.unique_customers >= 4 ORDER BY 4 DESC, id;
